  RegisterSchema(OpSchema()
      .SetName("DequantizeLinear")
      .SetDomain("")
      .SinceVersion(10)
      .Input(0, "x", "N-D quantized input tensor to be de-quantized.", "T", OpSchema::Single)
      .Input(1, "x_scale", "Scale for input 'x'. It's a scalar, which means a per-tensor/layer quantization.", "tensor(float)", OpSchema::Single)
      .Input(2, "x_zero_point", "Zero point for input 'x'. It's a scalar, which means a per-tensor/layer quantization. It's optional. 0 is the default value when it's not specified.", "T", OpSchema::Optional)
      .Output(0, "y", "N-D full precision output tensor. It has same shape as input 'x'.", "tensor(float)", OpSchema::Single)
      .TypeConstraint("T", {"tensor(int8)", "tensor(uint8)", "tensor(int32)"}, "Constrain 'x_zero_point' and 'x' to 8-bit/32-bit integer tensor.")
      .SetDoc(R"DOC(
The linear dequantization operator. It consumes a quantized tensor, a scale, a zero point to compute the full precision tensor.
The dequantization formula is y = (x - x_zero_point) * x_scale. 'x_scale' and 'x_zero_point' are both scalars.
'x_zero_point' and 'x' must have same type. 'x' and 'y' must have same shape. In the case of dequantizing int32,
there's no zero point (zero point is supposed to be 0).
)DOC"), 0, false, false);

