  RegisterSchema(OpSchema()
      .SetName("Upsample")
      .SetDomain("")
      .SinceVersion(1)
      .Input(0, "X", "4-D tensor, [N,C,H,W]", "T", OpSchema::Single)
      .Output(0, "Y", "4-D tensor after resizing, [N,C,H,W]", "T", OpSchema::Single)
      .TypeConstraint("T", {"tensor(bool)", "tensor(int32)", "tensor(int64)", "tensor(float16)", "tensor(float)", "tensor(double)"}, "Constrain output types to bool, int32, int64, float16, float, double tensors.")
      .SetDoc(R"DOC(
Upsample the input tensor.
The width and height of the output tensor are:
  output_width = floor(input_width * width_scale),
  output_height = floor(input_height * height_scale).
Example:
  Given `data` tensor, width_scale, height_scale, mode,
  Upsample the input 4-D tensor in nearest mode:
  data = [[[
      [1, 2],
      [3, 4]
  ]]]
  width_scale = 2
  height_scale = 2
  mode = "nearest"
  output = [[[
      [1, 1, 2, 2],
      [1, 1, 2, 2],
      [3, 3, 4, 4],
      [3, 3, 4, 4]
  ]]]
)DOC")
      .SetSupportLevel(OpSchema::SupportType::EXPERIMENTAL), 0, false, false);

